(async()=>{const out={};for(const attrs of ['','width="100"','height="100"','viewBox="0 0 10 20"','width="100" viewBox="0 0 10 20"','height="100" viewBox="0 0 10 20"','width="50%" height="50%" viewBox="0 0 10 20"','width="1in" height="2cm"','width="0" height="0"','width="-1" height="7"']){document.title=attrs;const i=new Image();i.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" '+attrs+'/>');out[attrs]=await i.decode().then(()=>[i.naturalWidth,i.naturalHeight],e=>e.name)}document.title='done';return out})()
